"""Static, indexable resource catalog pages."""
import json
from disclaimers import notice
from html import escape as e

def build_resources(root,page):
 templates=json.loads((root/'public/data/hr-templates.json').read_text(encoding='utf-8'))
 manifest={t['id']:t for t in json.loads((root/'public/data/hr-template-manifest.json').read_text(encoding='utf-8'))}
 for t in templates:
  t.update({key:manifest[t['id']][key] for key in ['fields','formulaColumns','note','format','previews','sections']})
 sites=json.loads((root/'public/data/official-sites.json').read_text(encoding='utf-8'))
 common=notice('resources')
 feedback='<section class="panel feedback-panel" id="tool-feedback"><h2>吐槽一下这个模块</h2><p>匿名提交后公开显示，请勿提供员工个人资料。</p><form id="feedback-form"><label class="field"><span>你的反馈</span><textarea name="message" required minlength="2" maxlength="1000" rows="3"></textarea></label><button class="button primary">匿名提交</button><p id="feedback-status" role="status"></p></form><div id="feedback-list"></div></section><script type="module" src="/assets/feedback.js"></script>'
 tail=common+feedback+'<script type="module" src="/assets/resources.js"></script>'
 font_note='<p class=panel-subtitle>模板统一使用 Noto Sans CJK SC。未安装时可能被替换；<a href="/downloads/template-fonts/font-package.zip" download>下载免费商用字体包</a>，安装一次即可。整包与分类包已附字体及授权。</p>'
 categories=list(dict.fromkeys(t['category'] for t in templates))
 cards=''.join(f'<article class="resource-card" data-category="{t["category"]}" data-format="{t["format"]}" data-search="{e(t["title"]+t["description"]+" ".join(t["fields"]))}"><a class="template-thumb" href="/templates/{t["id"]}/"><img src="{t["previews"][0]}" alt="{t["title"]}实际文件预览" loading="lazy"></a><span class="resource-tag">{t["category"]} · {"Word 表单" if t["format"]=="docx" else "Excel 工作表"}</span><h2><a href="/templates/{t["id"]}/">{t["title"]}</a></h2><p>{t["description"]}</p><div class="resource-actions"><a href="/templates/{t["id"]}/">查看成品 →</a><button class="button" data-download="{t["id"]}">下载 {"Word" if t["format"]=="docx" else "Excel"}</button></div></article>' for t in templates)
 filters='<div class="resource-filters"><label class="field">分类<select id="resource-category"><option value="">全部分类</option>'+''.join(f'<option>{c}</option>' for c in categories)+'</select></label><label class="field">搜索表格<input id="resource-search" type="search" placeholder="面试、交接、考勤、清单…"></label><label class="field">文件类型<select id="resource-format"><option value="">全部格式</option><option value="docx">Word</option><option value="xlsx">Excel</option></select></label><button class="button" id="download-category">打包下载全部模板</button></div>'
 pack_banner=f'<div class="template-pack-banner"><div><strong>HR 模板整包</strong><p>{len(templates)} 份 Word / Excel，按工作场景分文件夹。</p></div><a class="button primary" id="download-all-templates" href="/downloads/hr-templates/all-templates.zip" download="HR模板合集.zip">全部模板一键下载（ZIP）</a></div>'
 page('/templates/','HR 表格库' ,'64份HR表格和清单：招聘面试、入职转正、考勤休假、薪酬福利、培训发展、绩效人才、员工关系及离职交接。','<div class="page-intro"><div class="eyebrow">HR TEMPLATE LIBRARY</div><h1>HR 表格库</h1><p>8 类 · 64 份工作模板。26 份 Word 表单，38 份 Excel 工作表。</p></div><p class="local-banner">面试评价、审批表单、工作台账、办理清单按场景设计。预览来自实际文件；Word 可填写打印，Excel 含筛选、冻结表头及适用公式。整包和分类包均包含原格式可编辑文件。</p>'+pack_banner+font_note+filters+'<p id="resource-status" role="status">64 份模板</p><div class="resource-grid">'+cards+'</div>'+tail,'templates','hr-templates')
 for t in templates:
  rows=''.join('<tr><th>'+e(f)+'</th><td class="blank-field">&nbsp;</td></tr>' for f in t['fields'])
  fmt='Word' if t['format']=='docx' else 'Excel'
  preview=''.join(f'<figure class="template-page"><a href="{url}" target="_blank" rel="noopener"><img class="workbook-preview" src="{url}" alt="{t["title"]} 成品预览 {i+1}" loading="lazy"></a><figcaption>{"第 " + str(i+1) + " 页" if fmt=="Word" else "概览" if len(t["previews"])>1 and i==0 else "明细工作表（部分行预览）"}</figcaption></figure>' for i,url in enumerate(t['previews']))
  sections=' · '.join(t['sections'])
  formulas='、'.join(t['formulaColumns']) or '无自动计算，按实际业务填写'
  body=f'<a class="back-link" href="/templates/">← 返回 HR 表格库</a><div class="page-intro"><div class="eyebrow">{t["category"]} / {fmt}</div><h1>{t["title"]}</h1><p>{t["description"]}</p></div><div class="resource-actions"><button class="button primary" data-download="{t["id"]}">下载可编辑 {fmt}</button><button class="button" id="print-template">打印网页预览</button></div><p id="resource-status" role="status"></p><section class="panel printable-template"><h2>成品预览</h2><p>{e(sections)}</p><p>{e(t["note"])}</p><p>公式：{e(formulas)}。打印完整文件请在 Word 或 Excel 中使用下载文件。</p>{font_note}{preview}<details><summary>查看包含字段</summary><table class="form-preview"><tbody>{rows}</tbody></table></details></section>'+tail
  page('/templates/'+t['id']+'/',t['title'],t['description'],body,'template-detail','hr-templates')
 cats=list(dict.fromkeys(t['category'] for t in sites));regions=list(dict.fromkeys(t['region'] for t in sites))
 filters='<div class="resource-filters"><label class="field">业务分类<select id="resource-category"><option value="">全部业务</option>'+''.join(f'<option>{c}</option>' for c in cats)+'</select></label><label class="field">地区<select id="resource-region"><option value="">全部地区</option>'+''.join(f'<option>{c}</option>' for c in regions)+'</select></label><label class="field">搜索官网<input id="resource-search" type="search" placeholder="社保、个税、公积金…"></label></div>'
 cards=''.join(f'<article class="resource-card" data-category="{t["category"]}" data-region="{t["region"]}" data-search="{e(t["name"]+t["description"])}"><span class="resource-tag">{t["region"]} · {t["category"]}</span><h2><a href="{e(t["url"])}" target="_blank" rel="noopener noreferrer">{t["name"]} ↗</a></h2><p>{t["description"]}</p><small class="site-domain">{e(t["url"].split("/")[2])}</small></article>' for t in sites)
 page('/official-sites/','HR 官网导航','人社、社保、医保、公积金、税务和法律法规官方入口，按地区和业务分类查找。','<div class="page-intro"><div class="eyebrow">OFFICIAL HR SOURCES</div><h1>HR 官网导航</h1><p>找政策、查口径、办业务，从发布机关开始。</p></div><p class="local-banner">42 个公开来源核对的官方入口 · 整理日期 2026-09-27。入口不等于具体政策，部分网站可能需要登录或暂时无法访问；未保证实时可用。</p>'+filters+'<p id="resource-status" role="status">42 个入口</p><div class="resource-grid">'+cards+'</div>'+tail,'official-sites','official-sites')
 form='<form id="contract-form" class="panel"><h2>登记到期事项</h2><div class="form-grid"><label class="field">合同 / 事项编号<input name="label" maxlength="80" required placeholder="如：劳动合同-员工001"></label><label class="field">到期日期<input name="end" type="date" required></label><label class="field">提前提醒天数<input name="lead" type="number" min="0" max="365" step="1" value="30" required></label><label class="field">备注（选填）<input name="note" maxlength="200" placeholder="仅记录必要事项"></label></div><div class="form-actions"><button class="button primary" type="submit">保存提醒</button><button class="button" type="reset">取消编辑 / 清空</button></div><p id="contract-status" role="status"></p></form>'
 page('/contract-reminders/','合同到期提醒','本机保存合同到期日，打开网站时查看即将到期和已到期事项。','<div class="page-intro"><div class="eyebrow">CONTRACT REMINDERS</div><h1>合同到期提醒</h1><p>把待办日期记下来，提前安排跟进。</p></div><p class="local-banner">仅保存在当前浏览器，打开网页时显示；不发送短信、邮件或后台推送。提醒天数由你设定，不代表法定通知期限。清理浏览器数据会删除记录，请及时导出备份。</p>'+form+'<section class="panel" style="margin-top:24px"><div class="section-heading"><h2>到期事项</h2><button class="button" id="export-contracts">导出 Excel</button></div><div id="contract-list"></div></section>'+tail,'contract-reminders','contract-reminders')
